const ids=[7407,7405,7398,7272,38,33,5]; const UA='Mozilla/5.0 Chrome/140.0';
for(const id of ids){for(const base of ['/wp-json/wp/v2/elementor_library/','/?rest_route=/wp/v2/elementor_library/']){try{const path=base+id+(base.startsWith('/?')?'&x='+Date.now():'?x='+Date.now());const r=await fetch('https://signup.riseup.co.il'+path,{redirect:'manual',headers:{'user-agent':UA,'accept':'application/json','cache-control':'no-cache'}});const b=await r.text();let summary={id,base,status:r.status,len:b.length,ct:r.headers.get('content-type'),body:b.slice(0,1000)};try{const j=JSON.parse(b); summary={id,base,status:r.status,len:b.length,slug:j.slug,statusPost:j.status,contentLen:j.content?.rendered?.length||0,content:(j.content?.rendered||'').slice(0,3000)}}catch{}console.log('LIB',JSON.stringify(summary));}catch(e){console.log('ERR',id,base,String(e))}}}
